import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";

import * as Avatar from "../../ui/shadcn-avatar";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

const avatarImageSrc =
  "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 80 80'%3E%3Crect width='80' height='80' fill='%230f172a'/%3E%3Ctext x='40' y='48' text-anchor='middle' font-size='24' font-family='Arial' fill='white'%3ECN%3C/text%3E%3C/svg%3E";

export const view = Submodel.defineView<Model, Message>(() =>
  Avatar.rootView<Message>({
    children: [
      Avatar.imageView<Message>({
        alt: "Colm Tuite",
        src: avatarImageSrc,
      }),
      Avatar.badgeView<Message>({ label: "Online" }),
    ],
  })
);

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as ShadcnAvatarBadgeExample from "./main";

describe("shadcn Avatar Badge example", () => {
  test("renders an avatar with a status badge", () => {
    Scene.scene(
      {
        update: ShadcnAvatarBadgeExample.update,
        view: ShadcnAvatarBadgeExample.view,
      },
      Scene.with(ShadcnAvatarBadgeExample.init()[0]),
      Scene.expect(Scene.role("img", { name: "Colm Tuite" })).toExist(),
      Scene.expect(Scene.label("Online")).toExist(),
      Scene.expect(Scene.role("img", { name: "Colm Tuite" })).not.toHaveHandler(
        "click"
      )
    );
  });
});
